#!/usr/bin/env node
/**
 * PreToolUse hook — deny writes to files that must never be hand-modified.
 *
 * Two classes of path are protected:
 *
 * 1. Build output. Everything under `<module>/src/main/frontend/generated/` and every
 *    `vite.generated.ts` is regenerated by Vaadin on each build, so a hand edit
 *    is silently discarded and the next `bootRun` reintroduces the bug. This is
 *    CLAUDE.md's "Never edit generated files" rule made enforceable.
 *
 * 2. Graders. `.claude/skills/deck-run/driver.mjs` and its `shots/` baselines are
 *    this repo's only verification harness (there are no automated tests).
 *    Editing the thing that decides pass/fail is the cheapest way to turn a
 *    failing check green, so the harness is off-limits to the agent it grades.
 *    `.claude/hooks/` is included for the same reason: a guard that can rewrite
 *    itself is not a guard.
 *
 * Contract (docs: https://code.claude.com/docs/en/hooks):
 *   match    → print {"hookSpecificOutput":{"hookEventName":"PreToolUse",
 *              "permissionDecision":"deny","permissionDecisionReason":"..."}} and exit 0
 *   no match → exit 0, no output (normal permission flow applies)
 *   any error → exit 0 silently; a broken hook must not block every edit
 */

const PROTECTED = [
  {
    re: /(^|\/)(cms|command-deck)\/src\/main\/frontend\/generated\//,
    why: 'Vaadin regenerates this directory on every build, so hand edits are discarded (CLAUDE.md: never edit generated files).',
  },
  {
    re: /(^|\/)vite\.generated\.ts$/,
    why: 'vite.generated.ts is written by the Vaadin build and overwritten on every run.',
  },
  {
    re: /(^|\/)\.claude\/skills\/deck-run\/driver\.mjs$/,
    why: 'driver.mjs is the repo\'s verification harness — a grader must not be edited by the code it grades.',
  },
  {
    re: /(^|\/)\.claude\/skills\/deck-run\/shots\//,
    why: 'deck-run/shots holds the screenshot baselines the harness compares against — editing a baseline fakes a pass.',
  },
  {
    re: /(^|\/)\.claude\/hooks\//,
    why: 'a hook must not be able to disable itself; ask the user to change .claude/hooks by hand.',
  },
];

function readStdin() {
  return new Promise((resolve) => {
    if (process.stdin.isTTY) {
      resolve('');
      return;
    }
    let data = '';
    const bail = setTimeout(() => resolve(data), 5000);
    process.stdin.setEncoding('utf8');
    process.stdin.on('data', (chunk) => {
      data += chunk;
    });
    process.stdin.on('end', () => {
      clearTimeout(bail);
      resolve(data);
    });
    process.stdin.on('error', () => {
      clearTimeout(bail);
      resolve(data);
    });
  });
}

/** Candidate paths out of tool_input, covering Edit/Write/MultiEdit/NotebookEdit. */
function candidatePaths(toolInput) {
  if (!toolInput || typeof toolInput !== 'object') return [];
  const out = [];
  for (const key of ['file_path', 'notebook_path', 'path', 'filePath']) {
    if (typeof toolInput[key] === 'string' && toolInput[key]) out.push(toolInput[key]);
  }
  if (Array.isArray(toolInput.edits)) {
    for (const edit of toolInput.edits) {
      if (edit && typeof edit.file_path === 'string' && edit.file_path) out.push(edit.file_path);
    }
  }
  return out;
}

/** Windows backslashes → forward slashes; drop drive letters; case-fold for matching. */
function normalise(p) {
  return p.replace(/\\/g, '/').replace(/^[A-Za-z]:/, '').replace(/^\/+/, '/').toLowerCase();
}

function deny(reason) {
  process.stdout.write(
    JSON.stringify({
      hookSpecificOutput: {
        hookEventName: 'PreToolUse',
        permissionDecision: 'deny',
        permissionDecisionReason: reason,
      },
    })
  );
}

async function main() {
  const raw = await readStdin();
  if (!raw.trim()) return;

  let payload;
  try {
    payload = JSON.parse(raw);
  } catch {
    return; // malformed payload: allow, never block on our own failure
  }

  for (const original of candidatePaths(payload && payload.tool_input)) {
    const p = normalise(original);
    for (const rule of PROTECTED) {
      if (rule.re.test(p)) {
        deny(`Blocked edit to ${original.replace(/\\/g, '/')}: ${rule.why}`);
        return;
      }
    }
  }
}

main().then(
  () => process.exit(0),
  () => process.exit(0)
);
